import { useState } from "react";
import useTechnicianData from "../hooks/useTechnicianData.js";
import "./Profile.css";

export default function Profile() {
  const profileData = useTechnicianData();
  const [profile, setProfile] = useState(profileData);
  const [formValues, setFormValues] = useState(profileData);
  const [isEditing, setIsEditing] = useState(false);
  const [showSignOutModal, setShowSignOutModal] = useState(false);

  if (!profile || !formValues) {
    return (
      <section className="profile-page">
        <div className="profile-loading">Loading profile…</div>
      </section>
    );
  }

  const initials = profile.name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  const handleAvatarClick = () => {
    alert("Upload a profile picture here or connect this button to an image picker.");
  };

  const handleInputChange = (field) => (event) => {
    setFormValues({ ...formValues, [field]: event.target.value });
  };

  const handleStatChange = (statField) => (event) => {
    setFormValues({
      ...formValues,
      stats: {
        ...formValues.stats,
        [statField]: event.target.value,
      },
    });
  };

  const handleSave = () => {
    setProfile(formValues);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setFormValues(profile);
    setIsEditing(false);
  };

  const handleSignOut = () => {
    localStorage.removeItem("token");
    window.location.href = "/";
  };

  return (
    <section className="profile-page">
      <div className="profile-card">
        <div className="profile-card-header">
          <div>
            <h1>My Profile</h1>
            <p className="profile-note">You’ll need to sign in to see your jobs.</p>
          </div>
          <div className="profile-header-actions">
            {isEditing && (
              <button className="secondary-btn" onClick={handleCancel}>
                Cancel
              </button>
            )}
            <button
              className={`primary-btn ${isEditing ? "primary-btn--save" : ""}`}
              onClick={isEditing ? handleSave : () => setIsEditing(true)}
            >
              {isEditing ? "Save Changes" : "Edit Profile"}
            </button>
          </div>
        </div>

        <div className="profile-summary">
          <div className="profile-avatar-wrapper">
            <div className="profile-avatar">{initials}</div>
            <button
              type="button"
              className="avatar-action"
              onClick={handleAvatarClick}
              aria-label="Change profile picture"
            >
              +
            </button>
          </div>

          <div className="profile-details">
            {isEditing ? (
              <input
                className="profile-input profile-input--name"
                value={formValues.name}
                onChange={handleInputChange("name")}
                placeholder="Full name"
              />
            ) : (
              <p className="profile-name">{profile.name}</p>
            )}

            {isEditing ? (
              <input
                className="profile-input"
                value={formValues.role}
                onChange={handleInputChange("role")}
                placeholder="Role"
              />
            ) : (
              <p className="profile-role">{profile.role}</p>
            )}

            <div className="status-row">
              {isEditing ? (
                <select
                  className="profile-select"
                  value={formValues.status}
                  onChange={handleInputChange("status")}
                >
                  <option>Active</option>
                  <option>Ready for work</option>
                  <option>Closed for the day</option>
                  <option>Offline</option>
                </select>
              ) : (
                <span className="profile-badge">{profile.status}</span>
              )}
            </div>
          </div>
        </div>

        <div className="profile-stats">
          <div className="profile-stat">
            {isEditing ? (
              <input
                className="profile-input profile-input--stat"
                value={formValues.stats.completedThisMonth}
                onChange={handleStatChange("completedThisMonth")}
              />
            ) : (
              <strong>{profile.stats.completedThisMonth}</strong>
            )}
            <span>Completed this month</span>
          </div>

          <div className="profile-stat">
            {isEditing ? (
              <input
                className="profile-input profile-input--stat"
                value={formValues.stats.avgJobDuration}
                onChange={handleStatChange("avgJobDuration")}
              />
            ) : (
              <strong>{profile.stats.avgJobDuration}</strong>
            )}
            <span>Avg. job duration</span>
          </div>

          <div className="profile-stat">
            {isEditing ? (
              <input
                className="profile-input profile-input--stat"
                value={formValues.stats.activeJobs}
                onChange={handleStatChange("activeJobs")}
              />
            ) : (
              <strong>{profile.stats.activeJobs}</strong>
            )}
            <span>Active jobs now</span>
          </div>
        </div>

        <div className="profile-contact">
          <div className="profile-field">
            <label htmlFor="email">Email</label>
            {isEditing ? (
              <input
                id="email"
                className="profile-input"
                value={formValues.email}
                onChange={handleInputChange("email")}
              />
            ) : (
              <p>{profile.email}</p>
            )}
          </div>

          <div className="profile-field">
            <label htmlFor="phone">Phone</label>
            {isEditing ? (
              <input
                id="phone"
                className="profile-input"
                value={formValues.phone}
                onChange={handleInputChange("phone")}
              />
            ) : (
              <p>{profile.phone}</p>
            )}
          </div>

          <div className="profile-field">
            <label htmlFor="role">Role</label>
            <p>{profile.role}</p>
          </div>
        </div>

        <button className="profile-signout" onClick={() => setShowSignOutModal(true)}>
          Sign Out
        </button>
      </div>

      {showSignOutModal && (
        <div className="modal-overlay">
          <div className="modal">
            <h2>Confirm Sign Out</h2>
            <p>Are you sure you want to sign out? You will need to log in again to see your jobs.</p>
            <div className="modal-actions">
              <button className="confirm-btn" onClick={handleSignOut}>
                Yes, Sign Out
              </button>
              <button className="cancel-btn" onClick={() => setShowSignOutModal(false)}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}
